import React, { useState } from "react";

export default function Navbar({ isLogin, onLogin, onLogout }) {
  const [menuOpen, setMenuOpen] = useState(false);

  const links = [
    { name: "Home", id: "homePage" },
    { name: "About Us", id: "About" },
    { name: "Contact", id: "contact" },
    { name: "Blog", id: "Blog" },
  ];

  return (
    <nav style={styles.navbar}>
      {/* Logo */}
      <a href="#homePage">
        {isLogin ? (
          <div style={styles.logoLetter}>D</div>
        ) : (
          <img
            src="/Modern logo design f.png"
            alt="DailyCode Logo"
            style={styles.logoImg}
          />
        )}
      </a>

      {/* Links */}
      <ul
        style={{
          ...styles.navLinks,
          ...(menuOpen ? styles.showMenu : {}),
        }}
      >
        {links.map((link, i) => (
          <li key={i}>
            <a href={`#${link.id}`} style={styles.link}>
              {link.name}
            </a>
          </li>
        ))}

        {/* ✅ LOGIN / LOGOUT */}
        {!isLogin ? (
          <li>
            <span
              style={styles.link}
              onClick={() => {
                onLogin();       // open login modal
                setMenuOpen(false);
              }}
            >
              Log in
            </span>
          </li>
        ) : (
          <li>
            <span
              style={styles.link}
              onClick={() => {
                onLogout();      // clear login
                setMenuOpen(false);
              }}
            >
              Logout
            </span>
          </li>
        )}
      </ul>

      {/* Hamburger Button */}
      <button
        style={styles.menuBtn}
        onClick={() => setMenuOpen(!menuOpen)}
      >
        {menuOpen ? "✖" : "☰"}
      </button>
    </nav>
  );
}
